import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// ESQUADRIA 10X (cliente bruno nunes, gestor de tráfego): anúncio para donos de empresas de esquadrias. Agência
// especializada em esquadrias: mais orçamentos, vendas e faturamento; caso de cliente 50 mil → 180 mil em 30 dias.
// Identidade: logo (círculo off-white, barras turquesa, seta azul-petróleo subindo) + Instagram (azul-marinho, branco,
// Poppins pesada em itálico, fotos de esquadrias de vidro). Pouco material (logo + 6 recortes dos posts) → motion.
// Elemento-fio: a linha que sobe do logo (desenha no gancho, cai no "perigoso", vira o gráfico do caso, volta no fim).
// Voz o locutor (multilingual v2, (arquivo do cliente)), entra em 0,2 s; v() converte tempo da voz.

const { fontFamily: PP } = loadPoppins("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });
loadPoppins("italic", { weights: ["700", "800"], subsets: ["latin", "latin-ext"] });

export const E10_FPS = 30;
const VO = 0.2;
export const E10_FRAMES = Math.round(38.6 * E10_FPS);

const NAVY = "#0C1A33";
const NAVY2 = "#16305C";
const BLUE = "#21417A";
const TEAL = "#54C1C6";
const PETROL = "#002D40";
const PAPER = "#F5F6F0";
const WHITE = "#FFFFFF";
const SUB = "#A9B8CF";
const CORAL = "#FF6B5B";
const asset = (f: string) => staticFile(`brunonunes/${f}`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const IN = Easing.in(Easing.cubic);
const BACK = Easing.out(Easing.back(1.3));
const k = (t: number, a: number, d = 0.45, e = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
const kin = (t: number, a: number, d = 0.3) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const v = (s: number) => s + VO;
// tamanho que cabe na coluna de 840 px (Poppins pesada, caixa-alta ≈ 0,7 da altura por letra)
const fit = (s: string, size: number, max = 840) => Math.min(size, max / (s.length * 0.7));

// ───────── texto: sobe da linha por máscara e fica parado; sai descendo pela máscara ─────────
const Ln: React.FC<{ t: number; a: number; b?: number; size: number; color?: string; w?: number; it?: boolean; ls?: string; children: string }> = ({ t, a, b = 999, size, color = WHITE, w = 800, it = true, ls = "-0.01em", children }) => {
  const e = k(t, a, 0.5);
  const p = k(t, a, 0.55, BACK);
  const o = kin(t, b, 0.22);
  if (t < a || o >= 1) return null;
  return (
    <div style={{ overflow: "hidden", padding: `${size * 0.16}px ${size * 0.2}px ${size * 0.08}px`, margin: `${-size * 0.16}px ${-size * 0.2}px ${-size * 0.08}px` }}>
      <div style={{ fontFamily: PP, fontWeight: w, fontStyle: it ? "italic" : "normal", fontSize: size, lineHeight: 1.06, letterSpacing: ls, whiteSpace: "nowrap", textAlign: "center", textTransform: "uppercase", color, transform: `translateY(${((1 - e) * 110 + o * 110).toFixed(2)}%) scale(${(1.1 - 0.1 * p).toFixed(4)})` }}>{children}</div>
    </div>
  );
};
// rótulo pequeno: caixa-alta espaçada entre dois traços turquesa
const Label: React.FC<{ t: number; a: number; b?: number; color?: string; size?: number; children: string }> = ({ t, a, b = 999, color = TEAL, size = 36, children }) => {
  const e = k(t, a, 0.45) * (1 - kin(t, b, 0.22));
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 20, opacity: e, fontFamily: PP, fontWeight: 600, fontSize: size, letterSpacing: "0.26em", color, whiteSpace: "nowrap" }}>
      <span style={{ width: 60 * e, height: 4, borderRadius: 2, background: color }} />
      <span style={{ marginRight: "-0.26em" }}>{children}</span>
      <span style={{ width: 60 * e, height: 4, borderRadius: 2, background: color }} />
    </div>
  );
};
const Col: React.FC<{ top: number; gap?: number; style?: React.CSSProperties; children: React.ReactNode }> = ({ top, gap = 0, style, children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);
// fundo liso azul-marinho com uma luz suave que anda devagar
const Fundo: React.FC<{ t: number; y?: number; light?: boolean }> = ({ t, y = 46, light }) => (
  <AbsoluteFill style={{ background: light ? PAPER : NAVY }}>
    <AbsoluteFill style={{ background: light ? `radial-gradient(ellipse 80% 50% at ${(50 + Math.sin(t * 0.6) * 14).toFixed(1)}% ${y}%, rgba(84,193,198,0.16) 0%, rgba(245,246,240,0) 70%)` : `radial-gradient(ellipse 90% 55% at ${(50 + Math.sin(t * 0.6) * 16).toFixed(1)}% ${y}%, rgba(33,65,122,0.85) 0%, rgba(12,26,51,0) 72%)` }} />
  </AbsoluteFill>
);
// foto de esquadria num quadro w×h, cobrindo, com zoom e foco
const DIM: Record<string, [number, number]> = {
  "esq-1-sala-vista": [1587, 774], "esq-2-sala-jardim": [1920, 954], "esq-3-porta-correr": [864, 1920],
  "esq-4-casa-piscina": [1224, 768], "esq-5-fachada-vidro": [1551, 1095], "esq-6-sala-pe-direito": [1200, 720],
};
const Shot: React.FC<{ n: string; w: number; h: number; z?: number; fx?: number; fy?: number; style?: React.CSSProperties }> = ({ n, w, h, z = 1, fx = 0.5, fy = 0.5, style }) => {
  const [iw, ih] = DIM[n];
  const s = Math.max(w / iw, h / ih) * z;
  const W = iw * s;
  const H = ih * s;
  const cx = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));
  return (
    <div style={{ position: "absolute", width: w, height: h, overflow: "hidden", ...style }}>
      <Img src={asset(`${n}.jpg`)} style={{ position: "absolute", width: W, height: H, left: cx(w / 2 - fx * W, w - W, 0), top: cx(h / 2 - fy * H, h - H, 0) }} />
    </div>
  );
};
const Logo: React.FC<{ w: number; style?: React.CSSProperties }> = ({ w, style }) => <Img src={asset("logo.png")} style={{ width: w, height: w, display: "block", ...style }} />;
// varrida em diagonal: turquesa e azul passam e trocam a cena
const Blade: React.FC<{ t: number; at: number; dir?: 1 | -1 }> = ({ t, at, dir = 1 }) => {
  if (t < at - 0.3 || t > at + 0.34) return null;
  return (
    <AbsoluteFill style={{ overflow: "hidden", zIndex: 30 }}>
      {[TEAL, NAVY2].map((c, i) => {
        const p = interpolate(t, [at - 0.28 + i * 0.06, at + 0.22 + i * 0.06], [0, 1], { ...cl, easing: IN_OUT });
        const x = dir > 0 ? -2400 + p * 4600 : 2200 - p * 4600;
        return <div key={i} style={{ position: "absolute", left: x, top: -300, width: 1700, height: 2600, background: c, transform: `skewX(${dir * -16}deg)` }} />;
      })}
    </AbsoluteFill>
  );
};

// ───────── ícones em traço (desenham-se) ─────────
const S = (c: string = TEAL, w = 8) => ({ fill: "none", stroke: c, strokeWidth: w, strokeLinecap: "round" as const, strokeLinejoin: "round" as const });
const draw = (e: number) => ({ pathLength: 1, strokeDasharray: 1, strokeDashoffset: 1 - e });

// ───────── cena 1 (0–2,65 s): a esquadria se desenha, as folhas correm e mostram as obras ─────────
const STROBE = ["esq-1-sala-vista", "esq-5-fachada-vidro", "esq-4-casa-piscina", "esq-6-sala-pe-direito", "esq-2-sala-jardim", "esq-1-sala-vista"];
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const X = 190, Y = 330, WW = 700, HH = 800;
  const dr = k(t, 0, 0.55);
  const open = io(t, v(0.7), 0.45); // folha da esquerda corre para a direita
  const zoom = kin(t, 2.25, 0.4); // mergulho no vidro → próxima cena
  const cam = 1 + lin(t, 0, 2.3) * 0.05 + zoom * 7;
  const st = v(0.76);
  const idx = t < st ? 0 : Math.min(STROBE.length - 1, Math.floor((t - st) / 0.16));
  const tint = lin(t, 2.12, 2.42);
  return (
    <AbsoluteFill>
      <Fundo t={t} y={40} />
      <div style={{ position: "absolute", inset: 0, transform: `scale(${cam.toFixed(4)})`, transformOrigin: `${540}px ${Y + HH / 2}px` }}>
        {/* vão da esquadria: foto por trás do vidro */}
        <div style={{ position: "absolute", left: X + 14, top: Y + 14, width: WW - 28, height: HH - 28, overflow: "hidden", background: "#0A1730", opacity: dr }}>
          <Shot n={STROBE[idx]} w={WW - 28} h={HH - 28} z={1.05 + lin(t, st, 2.4) * 0.12} fx={0.5} fy={0.5} style={{ opacity: k(t, st, 0.12) }} />
          <AbsoluteFill style={{ background: NAVY, opacity: tint }} />
          {/* folha fixa (direita) e folha que corre (esquerda): vidro com reflexo */}
          {[0, 1].map((i) => {
            const left = i === 1 ? (WW - 28) / 2 : open * ((WW - 28) / 2 - 8);
            return (
              <div key={i} style={{ position: "absolute", left, top: 0, width: (WW - 28) / 2, height: HH - 28, boxSizing: "border-box", border: `12px solid #C9D3DF`, background: `linear-gradient(115deg, rgba(160,200,230,${0.32 - 0.22 * Math.min(1, open * 2)}) 0%, rgba(255,255,255,${0.1}) 40%, rgba(160,200,230,0.06) 100%)`, boxShadow: i === 0 ? "8px 0 24px rgba(0,0,0,0.35)" : undefined, zIndex: i === 0 ? 2 : 1 }}>
                <div style={{ position: "absolute", left: i === 0 ? WW / 2 - 64 : 14, top: (HH - 28) / 2 - 50, width: 10, height: 100, borderRadius: 5, background: "#8E9AAA" }} />
              </div>
            );
          })}
        </div>
        {/* marco de alumínio que se desenha */}
        <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
          <rect x={X} y={Y} width={WW} height={HH} rx={6} {...S("#DCE3EC", 16)} {...draw(dr)} />
          <path d={`M${X - 40} ${Y + HH + 16} H${X + WW + 40}`} {...S(TEAL, 10)} {...draw(k(t, 0.25, 0.4))} />
        </svg>
      </div>
      {/* texto embaixo do vão; as duas frases ocupam o mesmo lugar */}
      <Col top={1200} gap={6} style={{ opacity: Math.max(0, 1 - zoom * 4) }}>
        <Ln t={t} a={v(0.0)} b={v(1.3)} size={66} w={700}>Dono de empresa de</Ln>
        <Ln t={t} a={v(0.72)} b={v(1.3)} size={fit("ESQUADRIAS", 150)} color={TEAL}>esquadrias,</Ln>
      </Col>
      <Col top={1200} gap={6} style={{ opacity: Math.max(0, 1 - zoom * 4) }}>
        <Ln t={t} a={v(1.42)} size={110}>Presta</Ln>
        <Ln t={t} a={v(1.68)} size={fit("ATENÇÃO.", 150)} color={TEAL}>atenção.</Ln>
      </Col>
    </AbsoluteFill>
  );
};

// ───────── cena 2 (2,65–11,05 s): alguém procura; quem aparece primeiro, você ou o concorrente? ─────────
const QUERY = "esquadrias perto de mim";
const Result: React.FC<{ t: number; at: number; nameAt: number; photo: string; name: string; sub: string; hi: boolean; dim: number }> = ({ t, at, nameAt, photo, name, sub, hi, dim }) => {
  const e = k(t, at, 0.5, BACK);
  const ne = k(t, nameAt, 0.4);
  const sh = (t * 1.6) % 1; // brilho do "carregando" antes do nome
  if (t < at) return null;
  return (
    <div style={{ position: "absolute", left: 120, width: 840, height: 300, borderRadius: 34, background: WHITE, boxShadow: "0 30px 70px rgba(0,0,0,0.4)", display: "flex", alignItems: "center", gap: 34, padding: "0 34px", boxSizing: "border-box", border: `6px solid ${hi ? TEAL : "transparent"}`, opacity: Math.min(1, e * 3) * (1 - dim * 0.55), transform: `translateX(${((1 - e) * 300).toFixed(1)}px) scale(${(1 - dim * 0.06).toFixed(3)})` }}>
      <Shot n={photo} w={250} h={220} z={1.1} style={{ position: "relative", borderRadius: 20, flexShrink: 0 }} />
      <div style={{ display: "flex", flexDirection: "column", gap: 10, minWidth: 0 }}>
        <div style={{ position: "relative", overflow: "hidden" }}>
          <div style={{ fontFamily: PP, fontWeight: 800, fontStyle: "italic", fontSize: fit(name.toUpperCase(), 84, 470), lineHeight: 1, color: BLUE, textTransform: "uppercase", whiteSpace: "nowrap", transform: `translateY(${((1 - ne) * 150).toFixed(1)}%)` }}>{name}</div>
          {ne < 1 ? <div style={{ position: "absolute", left: 0, top: "18%", width: 360, height: "64%", borderRadius: 12, opacity: 1 - ne, background: `linear-gradient(90deg, #E3E8EF ${(sh * 100 - 30).toFixed(0)}%, #F4F7FA ${(sh * 100).toFixed(0)}%, #E3E8EF ${(sh * 100 + 30).toFixed(0)}%)` }} /> : null}
        </div>
        <div style={{ fontFamily: PP, fontWeight: 500, fontSize: 30, color: "#5B6B82", whiteSpace: "nowrap" }}>{sub}</div>
        <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
          {[0, 1, 2, 3, 4].map((s) => (
            <svg key={s} width={30} height={30} viewBox="0 0 24 24"><path d="M12 2 L15 9 L22 9.5 L16.5 14 L18.5 21 L12 17 L5.5 21 L7.5 14 L2 9.5 L9 9 Z" fill="#F2B84B" /></svg>
          ))}
        </div>
      </div>
    </div>
  );
};
const Search: React.FC<{ t: number }> = ({ t }) => {
  const a = 2.65;
  const Q = v(5.3); // "A pergunta é"
  const typed = QUERY.slice(0, Math.floor(lin(t, v(3.25), v(4.35)) * (QUERY.length + 0.99)));
  const out1 = kin(t, Q - 0.22, 0.22);
  const bar = k(t, v(2.95), 0.5, BACK);
  const pin = k(t, v(4.27), 0.45, BACK);
  // resultados: você aparece primeiro; no "concorrente" ele passa na frente
  const sw = io(t, v(9.55), 0.6);
  const yA = mix(640, 980, sw);
  const yB = mix(980, 640, sw);
  const cam = lin(t, a, 11.1);
  return (
    <AbsoluteFill>
      <Fundo t={t} y={38} />
      {t < Q ? (
        <div style={{ position: "absolute", inset: 0, opacity: 1 - out1, transform: `translateY(${(-out1 * 80).toFixed(1)}px)` }}>
          <Col top={420} gap={4}>
            <Ln t={t} a={v(2.62)} size={76} w={700}>Todo dia alguém</Ln>
            <Ln t={t} a={v(3.02)} size={150} color={TEAL}>procura</Ln>
          </Col>
          {/* barra de busca */}
          <div style={{ position: "absolute", left: 120, top: 840, width: 840, height: 140, borderRadius: 70, background: WHITE, display: "flex", alignItems: "center", gap: 26, padding: "0 44px", boxSizing: "border-box", boxShadow: "0 24px 60px rgba(0,0,0,0.35)", opacity: Math.min(1, bar * 3), transform: `translateY(${((1 - bar) * 120).toFixed(1)}px) scale(${(1 + cam * 0.03).toFixed(4)})` }}>
            <svg width={56} height={56} viewBox="0 0 24 24" style={{ flexShrink: 0 }}><circle cx={10} cy={10} r={6.5} {...S(BLUE, 2.6)} /><path d="M15 15 L21 21" {...S(BLUE, 2.6)} /></svg>
            <div style={{ fontFamily: PP, fontWeight: 500, fontSize: 46, color: "#1C2B44", whiteSpace: "nowrap" }}>
              {typed}
              <span style={{ opacity: Math.sin(t * 16) > 0 ? 1 : 0, color: TEAL, fontWeight: 400 }}>|</span>
            </div>
          </div>
          {/* "na sua cidade": pino que cai e o rótulo */}
          <Col top={1060} gap={26}>
            <svg width={120} height={150} viewBox="0 0 40 50" style={{ opacity: Math.min(1, pin * 3), transform: `translateY(${((1 - pin) * -160).toFixed(1)}px)` }}>
              <path d="M20 48 C20 48 4 30 4 18 A16 16 0 0 1 36 18 C36 30 20 48 20 48 Z" fill={TEAL} />
              <circle cx={20} cy={18} r={6.5} fill={NAVY} />
            </svg>
            <Ln t={t} a={v(4.3)} size={96}>na sua cidade.</Ln>
          </Col>
        </div>
      ) : (
        <>
          <Col top={310} gap={6}>
            <Label t={t} a={Q}>a pergunta é</Label>
            <Ln t={t} a={v(5.95)} size={70} w={700}>Essa pessoa</Ln>
            <Ln t={t} a={v(6.9)} size={70} w={700}>encontra...</Ln>
          </Col>
          <div style={{ position: "absolute", left: 0, right: 0, top: yA }}>
            <Result t={t} at={v(6.35)} nameAt={v(8.0)} photo="esq-6-sala-pe-direito" name="Você" sub="Sua empresa de esquadrias" hi={sw < 0.5} dim={sw} />
          </div>
          <div style={{ position: "absolute", left: 0, right: 0, top: yB, zIndex: 2 }}>
            <Result t={t} at={v(6.75)} nameAt={v(8.8)} photo="esq-5-fachada-vidro" name="Seu concorrente" sub="Esquadrias na sua cidade" hi={sw >= 0.5} dim={0} />
          </div>
          {/* "1º" na frente do card que está no topo */}
          <div style={{ position: "absolute", left: 0, right: 0, top: 1340, textAlign: "center", fontFamily: PP, fontWeight: 600, fontSize: 44, color: SUB, opacity: k(t, v(9.9), 0.4) }}>
            Quem aparece primeiro, <span style={{ color: TEAL, fontWeight: 800 }}>vende.</span>
          </div>
        </>
      )}
    </AbsoluteFill>
  );
};

// ───────── cena 3 (11,05–15,4 s): indicação é ótima; depender só dela é perigoso ─────────
const Indica: React.FC<{ t: number }> = ({ t }) => {
  const M = v(11.92); // "mas depender"
  const P = v(13.93); // "é perigoso"
  // linha das vendas que vivem de indicação: sobe e desce sem rumo e despenca no "perigoso"
  const pts = [[150, 1010], [260, 870], [360, 950], [470, 790], [570, 910], [670, 830], [770, 940], [870, 880]];
  const drawn = lin(t, M + 0.15, P);
  const fall = k(t, P, 0.5, IN_OUT);
  const last: [number, number] = [930, mix(880, 1210, fall)];
  const all = [...pts, last];
  const d = all.map((p, i) => `${i ? "L" : "M"}${p[0]} ${p[1]}`).join(" ");
  const shake = t > P && t < P + 0.3 ? Math.sin(t * 90) * 8 * (1 - (t - P) / 0.3) : 0;
  return (
    <AbsoluteFill>
      <Fundo t={t} y={34} />
      {t < M ? (
        <Col top={640} gap={30}>
          <svg width={170} height={170} viewBox="0 0 100 100" style={{ transform: `scale(${(0.6 + 0.4 * k(t, 11.1, 0.5, BACK)).toFixed(3)})` }}>
            <circle cx={50} cy={50} r={44} {...S(TEAL, 7)} {...draw(k(t, 11.1, 0.5))} />
            <path d="M30 52 L44 66 L72 36" {...S(TEAL, 9)} {...draw(k(t, 11.35, 0.4))} />
          </svg>
          <Ln t={t} a={v(11.1)} b={M - 0.2} size={fit("INDICAÇÃO", 140)}>Indicação</Ln>
          <Ln t={t} a={v(11.38)} b={M - 0.2} size={120} color={TEAL}>é ótima.</Ln>
        </Col>
      ) : (
        <>
          <Col top={330} gap={4}>
            <Ln t={t} a={M} size={64} w={700}>Mas depender só de</Ln>
            <Ln t={t} a={v(13.15)} size={fit("INDICAÇÃO", 130)} color={TEAL}>indicação</Ln>
          </Col>
          <svg width={1080} height={1920} style={{ position: "absolute", left: shake, top: 0 }}>
            <path d="M120 1230 H960" {...S("rgba(169,184,207,0.35)", 4)} />
            <path d={d} {...S(fall > 0 ? CORAL : WHITE, 12)} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - Math.min(1, drawn + fall)} />
            {fall > 0.9 ? <circle cx={last[0]} cy={last[1]} r={16} fill={CORAL} /> : null}
          </svg>
          <Col top={1300}>
            <Ln t={t} a={P} size={fit("É PERIGOSO.", 150)} color={CORAL}>é perigoso.</Ln>
          </Col>
        </>
      )}
    </AbsoluteFill>
  );
};

// ───────── cena 4 (15,4–19,95 s): virada para o claro; a Esquadria 10X, especializada em esquadrias ─────────
const Agencia: React.FC<{ t: number }> = ({ t }) => {
  const a = 15.4;
  const flood = k(t, a - 0.05, 0.55, IN_OUT);
  const lg = k(t, a + 0.1, 0.6, BACK);
  const thumbs = ["esq-4-casa-piscina", "esq-3-porta-correr", "esq-1-sala-vista"];
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      <AbsoluteFill style={{ clipPath: `circle(${(flood * 150).toFixed(2)}% at 50% 1400px)` }}>
        <Fundo t={t} light y={30} />
        <div style={{ position: "absolute", left: 0, right: 0, top: 300, display: "flex", justifyContent: "center", transform: `scale(${(0.5 + 0.5 * lg + lin(t, a, 20) * 0.04).toFixed(4)}) rotate(${((1 - lg) * -20).toFixed(2)}deg)`, opacity: Math.min(1, lg * 3) }}>
          <div style={{ position: "relative", width: 400, height: 400 }}>
            <Logo w={400} style={{ borderRadius: 200, boxShadow: "0 24px 60px rgba(12,26,51,0.25)" }} />
            {/* anel turquesa que se desenha em volta do logo enquanto a fala apresenta a agência */}
            <svg width={480} height={480} viewBox="0 0 480 480" style={{ position: "absolute", left: -40, top: -40, transform: `rotate(${(-90 + lin(t, a, 20) * 40).toFixed(1)}deg)` }}>
